<div class="page-heading"><div><div class="eyebrow">AKUN ANDA</div><h1>Profil & keamanan</h1><p>Perbarui informasi pribadi dan lindungi akses workspace Anda.</p></div><span class="subtle-badge"><?= e($profile['role']) ?></span></div><?php if($message): ?><div class="alert alert-danger" role="alert"><?= e($message) ?></div><?php endif; ?><div class="profile-grid"><section class="panel form-panel"><h2>Informasi profil</h2><p class="text-secondary mb-4">Identitas Anda pada catatan transaksi.</p><form method="post" action="/profile"><?= csrf_field() ?><?php foreach(['name'=>'Nama lengkap','email'=>'Email'] as $name=>$label): ?><div class="mb-3"><label class="form-label" for="<?= $name ?>"><?= $label ?></label><input class="form-control" id="<?= $name ?>" name="<?= $name ?>" type="<?= $name==='email'?'email':'text' ?>" value="<?= e($profile[$name]) ?>" required maxlength="<?= $name==='email'?150:100 ?>"><div class="field-error"><?= e($errors[$name]??'') ?></div></div><?php endforeach; ?><button class="btn btn-primary mt-2">Simpan profil</button></form></section><section class="panel form-panel" id="password-panel"><h2>Ganti password</h2><p class="text-secondary mb-4">Gunakan password unik, minimal 10 karakter.</p><form method="post" action="/profile/password"><?= csrf_field() ?><?php foreach(['current_password'=>'Password saat ini','password'=>'Password baru','password_confirmation'=>'Konfirmasi password baru'] as $name=>$label): ?><div class="mb-3"><label class="form-label" for="<?= $name ?>"><?= $label ?></label><input class="form-control" id="<?= $name ?>" type="password" name="<?= $name ?>" required maxlength="72" <?= $name!=='current_password'?'minlength="10"':'' ?> autocomplete="<?= $name==='current_password'?'current-password':'new-password' ?>"><div class="field-error"><?= e($errors[$name]??'') ?></div></div><?php endforeach; ?><button class="btn btn-primary mt-2">Perbarui password</button></form></section></div>
